window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3808f06bc66c77f8"]={"versions": [{"id": "FIG-3808f06bc66c77f8", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der statischen Abhängigkeiten des Softwaremoduls <code>E2E</code> (End-to-End Communication Protection Library) zu externen Schnittstellen der AUTOSAR-Basissoftware (BSW). Es visualisiert die verpflichtend vorauszusetzenden Routinen der CRC-Bibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das zentrale Element ist die Softwarekomponente bzw. das Modul <code>E2E</code> (Stereotyp «module»). Von diesem Modul gehen fünf gestrichelte gerichtete Abhängigkeitspfeile (Stereotyp «mandatory») auf externe funktionale Schnittstellen (Lollipop-Notation) aus:</p>\n<ul class=\"fig-list\"><li><code>Crc_CalculateCRC8</code>\n</li><li><code>Crc_CalculateCRC16</code>\n</li><li><code>Crc_CalculateCRC32P4</code>\n</li><li><code>Crc_CalculateCRC8H2F</code>\n</li><li><code>Crc_CalculateCRC64</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Komponentendiagramm modelliert das Schaubild keinen dynamischen Sequenzablauf und keine Zustandsübergänge. Die Aufrufe der benannten CRC-Berechnungsfunktionen erfolgen zur Laufzeit synchron durch die jeweiligen E2E-Profile (z. B. Profile 1, 2, 4, 5, 7) während der Absicherung (Protect) oder Prüfung (Check) von Datenpaketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die E2E-Bibliothek besitzt eine zwingende funktionale Abhängigkeit zu den spezifizierten Berechnungsfunktionen der BSW-Komponente <code>Crc</code>. Eine Implementierung des E2E-Moduls muss diese Crc-APIs zur Verfügung haben, um Prüfsummen berechnen und verifizieren zu können. Jede Schnittstelle ist explizit als «mandatory» gekennzeichnet.</p>"}, {"id": "FIG-98288027f7df7988", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der statischen Abhängigkeiten des Softwaremoduls <code>E2E</code> (End-to-End Communication Protection Library) zu externen Schnittstellen der AUTOSAR-Basissoftware (BSW). Es visualisiert die verpflichtend vorauszusetzenden Routinen der CRC-Bibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das zentrale Element ist die Softwarekomponente bzw. das Modul <code>E2E</code> (Stereotyp «module»). Von diesem Modul gehen fünf gestrichelte gerichtete Abhängigkeitspfeile (Stereotyp «mandatory») auf externe funktionale Schnittstellen (Lollipop-Notation) aus:</p>\n<ul class=\"fig-list\"><li><code>Crc_CalculateCRC8</code>\n</li><li><code>Crc_CalculateCRC16</code>\n</li><li><code>Crc_CalculateCRC32P4</code>\n</li><li><code>Crc_CalculateCRC8H2F</code>\n</li><li><code>Crc_CalculateCRC64</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Komponentendiagramm modelliert das Schaubild keinen dynamischen Sequenzablauf und keine Zustandsübergänge. Die Aufrufe der benannten CRC-Berechnungsfunktionen erfolgen zur Laufzeit synchron durch die jeweiligen E2E-Profile (z. B. Profile 1, 2, 4, 5, 7) während der Absicherung (Protect) oder Prüfung (Check) von Datenpaketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die E2E-Bibliothek besitzt eine zwingende funktionale Abhängigkeit zu den spezifizierten Berechnungsfunktionen der BSW-Komponente <code>Crc</code>. Eine Implementierung des E2E-Moduls muss diese Crc-APIs zur Verfügung haben, um Prüfsummen berechnen und verifizieren zu können. Jede Schnittstelle ist explizit als «mandatory» gekennzeichnet.</p>"}, {"id": "FIG-8a87e5a1c5512306", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der statischen Abhängigkeiten des Softwaremoduls <code>E2E</code> (End-to-End Communication Protection Library) zu externen Schnittstellen der AUTOSAR-Basissoftware (BSW). Es visualisiert die verpflichtend vorauszusetzenden Routinen der CRC-Bibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das zentrale Element ist die Softwarekomponente bzw. das Modul <code>E2E</code> (Stereotyp «module»). Von diesem Modul gehen fünf gestrichelte gerichtete Abhängigkeitspfeile (Stereotyp «mandatory») auf externe funktionale Schnittstellen (Lollipop-Notation) aus:</p>\n<ul class=\"fig-list\"><li><code>Crc_CalculateCRC8</code>\n</li><li><code>Crc_CalculateCRC16</code>\n</li><li><code>Crc_CalculateCRC32P4</code>\n</li><li><code>Crc_CalculateCRC8H2F</code>\n</li><li><code>Crc_CalculateCRC64</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Komponentendiagramm modelliert das Schaubild keinen dynamischen Sequenzablauf und keine Zustandsübergänge. Die Aufrufe der benannten CRC-Berechnungsfunktionen erfolgen zur Laufzeit synchron durch die jeweiligen E2E-Profile (z. B. Profile 1, 2, 4, 5, 7) während der Absicherung (Protect) oder Prüfung (Check) von Datenpaketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die E2E-Bibliothek besitzt eine zwingende funktionale Abhängigkeit zu den spezifizierten Berechnungsfunktionen der BSW-Komponente <code>Crc</code>. Eine Implementierung des E2E-Moduls muss diese Crc-APIs zur Verfügung haben, um Prüfsummen berechnen und verifizieren zu können. Jede Schnittstelle ist explizit als «mandatory» gekennzeichnet.</p>"}], "trans": [{"from": "FIG-3808f06bc66c77f8", "to": "FIG-98288027f7df7988", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-98288027f7df7988", "to": "FIG-8a87e5a1c5512306", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
